import hashlib,json,re,subprocess
patterns={'aws':re.compile(rb'AKIA[0-9A-Z]{16}'),'github':re.compile(rb'ghp_[A-Za-z0-9]{8,}'),'huggingface':re.compile(rb'hf_[A-Za-z0-9]{8,}')}
def git(cwd,*args): return subprocess.check_output(['git',*args],cwd=cwd)
current={k:0 for k in patterns}
for path in git('/app/dclm','ls-files','-z').split(b'\0'):
 if not path: continue
 b=open('/app/dclm/'+path.decode(),'rb').read()
 for kind,rx in patterns.items(): current[kind]+=len(rx.findall(b))
history=[]
commits=git('/app/dclm-review/prechange.git','rev-list','--all').decode().split()
for commit in commits:
 for line in git('/app/dclm-review/prechange.git','ls-tree','-r',commit).decode().splitlines():
  meta,path=line.split('\t',1); blob=meta.split()[2]
  b=git('/app/dclm-review/prechange.git','cat-file','blob',blob)
  for kind,rx in patterns.items():
   for match in rx.finditer(b):
    history.append({'commit':commit[:12],'path':path,'kind':kind,'sha256_prefix':hashlib.sha256(match.group()).hexdigest()[:12]})
json.dump({'current':current,'history':history},open('/app/history-status.json','w'),indent=2)
print(json.dumps({'current':current,'prechange_matches':len(history),'prechange_commits':sorted(set(x['commit'] for x in history)),'kinds':sorted(set(x['kind'] for x in history))}))
